def is_leap(year):
    """Check if a year is a leap year according to the Gregorian calendar rule.

    A year is a leap year if:
    - It is divisible by 4, except for century years (divisible by 100),
      which are leap years only if divisible by 400.
    """
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    if year % 4 == 0:
        return True
    return False

